<?php
function html_to_bbcode($html) {
 $safe=clean_html($html);$doc=new DOMDocument();libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8"><div id="zo-edit">'.$safe.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();
 $walk=function($n) use(&$walk){if($n instanceof DOMText)return $n->nodeValue;if(!($n instanceof DOMElement))return ''; $inside='';foreach($n->childNodes as $c)$inside.=$walk($c);$tag=strtolower($n->tagName);$tags=['b'=>'b','strong'=>'b','i'=>'i','em'=>'i','u'=>'u','blockquote'=>'quote','pre'=>'code','code'=>'code','ul'=>'list','ol'=>'list=1'];if(isset($tags[$tag])){$bb=$tags[$tag];return '['.$bb.']'.$inside.'[/'.explode('=',$bb)[0].']';}if($tag==='span'&&$n->hasAttribute('style')){foreach(explode(';',$n->getAttribute('style')) as $rule){$part=explode(':',$rule,2);if(count($part)!==2)continue;$k=trim($part[0]);$v=trim($part[1]);if($k==='color')$inside='[color='.$v.']'.$inside.'[/color]';if($k==='font-size')$inside='[size='.$v.']'.$inside.'[/size]';}return $inside;}if($tag==='img')return '[img]'.str_replace([']','['],['%5D','%5B'],$n->getAttribute('src')).'[/img]';if($tag==='a')return '[url='.str_replace([']','['],['%5D','%5B'],$n->getAttribute('href')).']'.$inside.'[/url]';if($tag==='li')return '[*]'.$inside."\n";if($tag==='br')return "\n";return $inside.(in_array($tag,['p','div','h1','h2','h3','tr'],true)?"\n":'');};
 return trim($walk($doc->getElementById('zo-edit')));
}
function post_permission($fid,$reply=false) {
 $u=current_user(true);native_core($u['uid']);global $_G;require_once libfile('function/forum');require_once libfile('function/post');loadforum($fid);$f=$_G['forum']??[];
 if(!$f||$f['type']==='group'||(int)$f['status']!==1)respond(null,404,'版块不存在');
 if($f['password']||app_formula_restricted($f['formulaperm'],$f)||$f['price'])respond(null,403,'该版块有额外访问条件，请先在论坛完成验证');
 if(($f['viewperm']&&!forumperm($f['viewperm']))||empty($_G['group']['readaccess'])||($f['allowview']??0)==-1)respond(null,403,'没有版块访问权限');
 $key=$reply?'replyperm':'postperm';$allow=$reply?'allowreply':'allowpost';if(($f[$allow]??0)==-1||($f[$key]?!forumperm($f[$key]):empty($_G['group'][$allow])))respond(null,403,'当前账号无发帖权限');
 if(!empty($_G['setting']['need_email'])&&empty($_G['member']['emailstatus']))respond(null,403,'请先在论坛验证邮箱');
 if(!empty($_G['setting']['need_secmobile'])&&empty($_G['member']['secmobilestatus']))respond(null,403,'请先在论坛完成手机认证');
 if(!empty($_G['setting']['accountguard']['postqqonly'])&&empty($_G['member']['conisbind']))respond(null,403,'论坛要求先绑定 QQ');
 if(!empty($_G['setting']['need_avatar'])&&empty($_G['member']['avatarstatus']))respond(null,403,'请先在论坛设置头像');
 if(!empty($_G['setting']['need_friendnum'])&&getuserprofile('friends')<(int)$_G['setting']['need_friendnum'])respond(null,403,'好友数量未满足论坛发帖条件');
 checklowerlimit($reply?'reply':'post',0,1,$fid);return $f;
}
function write_post($reply=false) {
 global $pdo,$_G;
 $u=current_user(true);rate('posting:'.$u['uid'],15,3600);$request=text_input('request_id',64);if(!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))respond(null,422,'请求标识无效');lock_user('post',$u['uid']);
 $pdo->exec('CREATE TABLE IF NOT EXISTS '.table('app_request').' (uid MEDIUMINT UNSIGNED NOT NULL,request_id VARCHAR(64) NOT NULL,result TEXT NOT NULL,created INT UNSIGNED NOT NULL,PRIMARY KEY(uid,request_id)) ENGINE=InnoDB');$old=one('SELECT result FROM '.table('app_request').' WHERE uid=? AND request_id=?',[$u['uid'],$request]);if($old)respond(json_decode($old['result'],true));
 $tid=$reply?id_input('tid'):0;$thread=$reply?one('SELECT * FROM '.table('forum_thread').' WHERE tid=?',[$tid]):null;if($reply&&!$thread)respond(null,404,'帖子不存在');
 $fid=$reply?(int)$thread['fid']:id_input('fid');post_permission($fid,$reply);if($reply&&((int)$thread['displayorder']<0||$thread['readperm']>$_G['group']['readaccess']||$thread['price']>0))respond(null,403,'帖子需要额外阅读权限');
 $subject=$reply?'':text_input('subject',240);if(!$reply&&mb_strlen($subject,'UTF-8')>80)respond(null,422,'标题最多80字');$html=text_input('content_html',150000);if(mb_strlen($html,'UTF-8')>50000)respond(null,422,'正文最多50000字');$message=html_to_bbcode($html);if(trim(strip_tags($html))===''&&strpos($message,'[img]')===false)respond(null,422,'请输入正文');
 $message=censor($message,null,true,false);$subject=censor($subject,null,true,false);if($message===false||$subject===false)respond(null,422,'内容包含论坛禁止发布的词语');
 $nativeAttach=[];$mapExists=one('SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[str_replace('`','',table('app_upload_native'))]);$ids=input('attach_ids',[]);if(!is_array($ids)||count($ids)>9)respond(null,422,'最多上传9张图片');foreach($ids as $aid){if(!is_numeric($aid))respond(null,422,'附件无效');$a=one('SELECT url FROM '.table('app_upload').' WHERE id=? AND uid=?',[(int)$aid,$u['uid']]);if(!$a)respond(null,403,'附件不属于当前账号');if($mapExists){$mapped=one('SELECT aid FROM '.table('app_upload_native').' WHERE uploadid=? AND uid=?',[(int)$aid,$u['uid']]);if($mapped){$unused=one('SELECT aid FROM '.table('forum_attachment_unused').' WHERE aid=? AND uid=?',[$mapped['aid'],$u['uid']]);if(!$unused)respond(null,422,'图片已用于其他帖子，请重新上传');$nativeAttach[(int)$mapped['aid']]=['description'=>'','readperm'=>0,'price'=>0];$message=str_replace('[img]'.$a['url'].'[/img]','[attach]'.$mapped['aid'].'[/attach]',$message);if(strpos($message,'[attach]'.$mapped['aid'].'[/attach]')===false)$message.='[attach]'.$mapped['aid'].'[/attach]';continue;}}if(strpos($message,$a['url'])===false)$message.="\n[img]".$a['url'].'[/img]';}
 $params=['subject'=>dhtmlspecialchars($subject),'message'=>$message,'clientip'=>$_SERVER['REMOTE_ADDR'],'special'=>0,'typeid'=>(int)input('typeid',0),'sortid'=>0,'publishdate'=>time(),'htmlon'=>0,'bbcodeoff'=>0,'smileyoff'=>0,'parseurloff'=>0,'usesig'=>0,'isanonymous'=>0,'readperm'=>0,'price'=>0,'tags'=>'','allownoticeauthor'=>1,'extramessage'=>''];
 if($reply)loadforum(null,$tid);$model=C::m($reply?'forum_post':'forum_thread');if($nativeAttach){$_GET['attachnew']=$nativeAttach;$model->attach_after_method($reply?'newreply':'newthread',['class'=>'extend_thread_image','method'=>$reply?'after_newreply':'after_newthread']);}$model->showmessage=function($key,$url='',$values=[]){throw new RuntimeException(strip_tags(lang('message',$key,$values)));};
 DB::query('START TRANSACTION');try {if($reply)$model->newreply($params);else $model->newthread($params);if(!$model->pid)throw new RuntimeException('发布未成功');$result=['tid'=>$reply?$tid:(int)$model->tid,'pid'=>(int)$model->pid,'moderated'=>(bool)$model->param($reply?'modnewreplies':'modnewthreads')];DB::insert('app_request',['uid'=>$u['uid'],'request_id'=>$request,'result'=>json_encode($result),'created'=>time()]);DB::query('COMMIT');respond($result);}catch(Throwable $e){DB::query('ROLLBACK');respond(null,422,$e->getMessage());}
}
